const D = { energy: .5, scale: 1, density: .55, speed: 1, ripple: .45, mist: .55, hue: 178, x: .5, y: .62, style: 'drowned', act: 'still', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 178;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NP = 4;                                   // trunk planes, 0 = farthest

// ---------------- styles ----------------
const STY = {
  // bleached drowned timber in cold still water — the anchor: eerie, austere, silent
  drowned:  { skyT:[196,18,46], skyL:[186,8,70], bark:[184,8,62], dark:[190,14,26], wat:[188,26,17],
              mist:[188,7,80], glint:[186,6,92], bare:1, wire:0, blot:0, grain:24 },
  // blackwater swamp at dusk — tannin-stained, warm, the trunks go to ochre silhouette
  cypress:  { skyT:[30,40,44], skyL:[38,46,76], bark:[32,26,44], dark:[22,44,18], wat:[26,52,12],
              mist:[36,20,66], glint:[42,32,88], bare:0, wire:0, blot:0, grain:32 },
  // moonlit — silver trunks, black water, dark key but never near-black
  nocturne: { skyT:[230,46,18], skyL:[212,20,44], bark:[206,8,58], dark:[218,22,17], wat:[214,30,10],
              mist:[204,10,52], glint:[196,6,90], bare:1, wire:0, blot:0, grain:16 },
  // ABSTRACTED: no mass at all — the trunks are contour wireframe, the water a survey grid
  wire:     { skyT:[220,60,18], skyL:[216,48,26], bark:[176,50,80], dark:[196,44,44], wat:[212,52,17],
              mist:[194,40,28], glint:[176,30,96], bare:1, wire:1, blot:0, grain:4 },
  // ABSTRACTED: the mirror makes this a Rorschach — pure silhouette, no interior, no modelling
  blot:     { skyT:[40,6,64], skyL:[40,4,78], bark:[220,20,7], dark:[220,24,5], wat:[42,5,58],
              mist:[40,3,84], glint:[40,2,94], bare:1, wire:0, blot:1, grain:10 }
};
const st = STY[P.style] || STY.drowned;

const en = Math.max(0, Math.min(1, P.energy));
const mi = Math.max(0, Math.min(1, P.mist));
const wy = height * P.y;                        // the waterline — the mirror
const rH = Math.max(4, Math.ceil(height - wy));
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.trees.remove(); S.refl.remove(); S.mist0.remove(); S.mist1.remove(); }
  S.sky = mk(W, H); S.trees = mk(W, H); S.refl = mk(W, rH);
  S.mist0 = mk(W, Math.max(2, wy + u * .06)); S.mist1 = mk(W, Math.max(2, wy + u * .06));

  const g = S.sky; g.noStroke();
  const cT = sh(st.skyT), cL = sh(st.skyL);
  for (let yy = 0; yy < H; yy++) { const c = L3(cT, cL, Math.pow(Math.min(1, yy / Math.max(1, wy)), .85)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  const barkC = sh(st.bark), darkC = sh(st.dark), mistC = sh(st.mist);

  // --- one dead standing trunk: taper, lean, a slow curve, bark striation, broken stubs ---
  const trunk = (q, x, h, w, id, col, edge, haze) => {
    const lean = (fr(id + 1) - .5) * .16;
    const segs = 12;
    const px = f => x + lean * h * f * f + Math.sin(f * 2.4 + fr(id + 2) * 6.3) * w * .8;
    const pw = f => w * (1 - f * .70) * (1 + .10 * Math.sin(f * 9.1 + fr(id + 3) * 6.3));
    const py = f => wy - h * f;
    if (st.wire) {
      q.noFill(); q.strokeWeight(Math.max(.5, u * .0011));
      q.stroke(col[0], col[1], col[2], 30 + 46 * (1 - haze));
      for (const sgn of [-1, 1]) { q.beginShape(); for (let i = 0; i <= segs; i++) { const f = i / segs; q.vertex(px(f) + sgn * pw(f) / 2, py(f)); } q.endShape(); }
      for (let i = 0; i <= segs; i += 2) { const f = i / segs; q.line(px(f) - pw(f) / 2, py(f), px(f) + pw(f) / 2, py(f)); }   // the contour rings
      q.noStroke();
    } else {
      q.noStroke(); q.fill(col[0], col[1], col[2], 100);
      q.beginShape();
      for (let i = 0; i <= segs; i++) { const f = i / segs; q.vertex(px(f) - pw(f) / 2, py(f)); }
      for (let i = segs; i >= 0; i--) { const f = i / segs; q.vertex(px(f) + pw(f) / 2, py(f)); }
      q.endShape(q.CLOSE);
      if (!st.blot) {
        // bark: vertical striation + a shaded side. Texture, never a flat fill.
        q.strokeWeight(Math.max(.4, w * .06));
        for (let s = 0; s < 7; s++) {
          const o = (s / 6 - .5) * .82;
          const lam = .5 + .5 * Math.cos((o - (P.x - .5) * 1.4) * 2.4);
          q.stroke(col[0], col[1] * (.8 + .4 * (1 - lam)), Math.max(2, col[2] * (.62 + .55 * lam) + (fr(id * 7 + s) - .5) * 8), 52);
          q.beginShape(); q.noFill();
          for (let i = 0; i <= segs; i++) { const f = i / segs; q.vertex(px(f) + o * pw(f) / 2, py(f)); }
          q.endShape();
        }
        q.noStroke();
      }
    }
    // broken branch stubs — snapped, never leafy. Bare trees only, unless the style keeps a crown.
    const nb = 2 + Math.floor(fr(id + 4) * 3);
    for (let b = 0; b < nb; b++) {
      const f = .45 + fr(id * 3 + b) * .5;
      const a = (fr(id * 5 + b) > .5 ? 1 : -1) * (.5 + fr(id * 7 + b) * .8);
      const bl = h * (.06 + fr(id * 11 + b) * .16);
      const bx = px(f), by = py(f);
      if (st.wire) { q.stroke(col[0], col[1], col[2], 40); q.strokeWeight(Math.max(.5, u * .001)); q.line(bx, by, bx + Math.cos(-Math.PI / 2 + a) * bl, by + Math.sin(-Math.PI / 2 + a) * bl); q.noStroke(); }
      else { q.stroke(col[0], col[1], Math.max(2, col[2] * .8), 100); q.strokeWeight(Math.max(.8, pw(f) * .3)); q.line(bx, by, bx + Math.cos(-Math.PI / 2 + a) * bl, by + Math.sin(-Math.PI / 2 + a) * bl); q.noStroke(); }
    }
    if (!st.bare && !st.wire && !st.blot) {      // cypress keeps a thin ragged crown
      q.fill(edge[0], edge[1], edge[2], 40);
      for (let c2 = 0; c2 < 5; c2++) q.ellipse(px(.9) + (fr(id + c2) - .5) * w * 5, py(.92) + (fr(id + c2 + 9) - .5) * w * 3, w * (2 + fr(id + c2) * 3), w * (1.2 + fr(id + c2) * 1.4));
    }
  };

  // --- draw the trunk field into BOTH the upright buffer and the mirrored one ---
  const paint = (q, flip) => {
    if (flip) { q.push(); q.translate(0, wy); q.scale(1, -1); }   // canvas y -> device (wy - y): a true mirror about the waterline
    for (let L = 0; L < NP; L++) {
      const near = L / (NP - 1);
      const haze = (1 - near) * (.28 + .55 * mi);
      const col = L3(L3(darkC, barkC, .3 + near * .7), mistC, haze);
      const edge = L3(barkC, mistC, haze * .7);
      const n = Math.max(1, Math.round((2 + fr(L * 13 + 1) * 3 + P.density * 5) * (L < 2 ? 1.6 : 1)));
      for (let i = 0; i < n; i++) {
        const id = L * 131 + i * 19 + 3;
        const x = width * ((i + .5 + (fr(id + 5) - .5) * .8) / n);
        const h = u * (.14 + near * .40 + fr(id + 6) * .18) * P.scale;
        const w = h * (.028 + fr(id + 7) * .028);
        trunk(q, x, h, Math.max(1.2, w), id, col, edge, haze);
      }
      // per-plane haze veil: the aerial-perspective separator
      if (!st.wire) { q.noStroke(); q.fill(mistC[0], mistC[1], mistC[2], (1 - near) * (8 + 26 * mi)); q.rect(0, 0, q.width, flip ? q.height : wy + 2); }
    }
    if (flip) q.pop();
  };
  paint(S.trees, false);
  paint(S.refl, true);

  // the reflection loses contrast and sinks into the water colour with distance from the mirror
  const watC = sh(st.wat); S.refl.noStroke();
  for (let i = 0; i < 26; i++) { const f = i / 26; S.refl.fill(watC[0], watC[1], watC[2], 4 + 62 * Math.pow(f, 1.5)); S.refl.rect(0, f * rH, W, rH / 26 + 1); }

  const mC = sh(st.mist);
  for (const [gg, n, yc, spr, thk, alp] of [[S.mist0, 9, wy - u * .10, u * .22, u * .05, 16], [S.mist1, 6, wy - u * .015, u * .10, u * .028, 20]]) {
    gg.noStroke();
    for (let i = 0; i < n; i++) {
      const bx = fr(i * 5 + 91) * W, by = yc + (fr(i * 5 + 92) - .5) * spr;
      const bw = u * (.24 + fr(i * 5 + 93) * .7), bhh = thk * (.5 + fr(i * 5 + 94));
      for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
        gg.fill(mC[0], mC[1] * (1 - kk * .1), Math.min(99, mC[2] + kk * 2), alp * (1 - kk * .2));
        gg.ellipse(bx + rep * W, by + kk * bhh * .14, bw * (1 - kk * .12), bhh * (1 - kk * .08));
      }
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { still: { r: .35 + sec * .02, m: 1 }, breath: { r: .5 + sec * .09, m: 1.1 - sec * .06 }, drown: { r: .8, m: .7 + sec * .12 } };
const act = ACT[P.act] || ACT.still;
const rip = Math.max(0, Math.min(1.4, P.ripple * (.5 + act.r)));
const mistAmt = Math.max(0, Math.min(1.5, act.m));

noStroke();
image(S.sky, 0, 0);
const W2 = S.mist0.width;
const scr = (g, px2, yy, a) => { const ox = ((px2 % W2) + W2) % W2; if (a < 100) tint(0, 0, 100, a); image(g, ox - W2, yy); image(g, ox, yy); if (a < 100) noTint(); };
scr(S.mist0, -K.t * u * .0029 * P.speed, 0, 100 * Math.min(1, mistAmt));

const ddx = (Math.sin(K.t * .015) * .7 + Math.sin(K.t * .0367 + 1.1) * .3) * u * .004 * P.speed;
image(S.trees, ddx, 0);

// ---------------- the mirror: the reflection redrawn as displaced horizontal strips ----------------
const watC2 = sh(st.wat);
fill(watC2[0], watC2[1], watC2[2]); rect(0, wy, width, height - wy);
const NS = 44;
const sh0 = rH / NS;
for (let i = 0; i < NS; i++) {
  const f = i / NS;                              // 0 at the mirror line -> 1 at the near edge
  // amplitude grows toward the camera, and three incommensurate terms keep it from re-phasing
  const amp = u * .012 * (.15 + f * 1.5) * (.25 + rip) * (.5 + .5 * en);
  const ph = K.t * P.speed;
  const dx = amp * (Math.sin(f * 11 + ph * .61) * .6 + Math.sin(f * 26 - ph * 1.43 + 1.7) * .28 + Math.sin(f * 5 + ph * 2.29) * .34);
  const sq = 1 + .06 * Math.sin(f * 17 + ph * .87);
  image(S.refl, ddx + dx, wy + i * sh0, width, sh0 * sq + 1, 0, i * sh0, S.refl.width, sh0 + .5);
}

// ---------------- water surface: glints and slow ripple rings ----------------
const glC = sh(st.glint);
if (!st.wire) {
  const ng2 = Math.floor(14 + P.density * 22);
  blendMode(P.style === 'nocturne' || P.style === 'drowned' ? ADD : BLEND);
  for (let i = 0; i < ng2; i++) {
    const f = Math.pow(fr(i * 7 + 301), 1.5);
    const gy = wy + f * (height - wy);
    const gx = fr(i * 7 + 302) * width;
    const sm = .5 + .5 * (Math.sin(K.t * (.61 + i * .013) + i) * .55 + Math.sin(K.t * 1.43 + i * 2.1) * .3 + Math.sin(K.t * 2.29 + i) * .15);
    const gain = (.3 + .7 * en) * (.35 + .65 * sm) + A.treble * .2;
    fill(glC[0], glC[1], glC[2], (6 + 26 * gain) * (.3 + f));
    ellipse(gx + Math.sin(K.t * .3 + i) * u * .006, gy, u * (.02 + .07 * sm) * (.3 + f * 1.6), u * .0035 * (.3 + f * 1.6));
  }
  blendMode(BLEND);
  // a few slow rings — something under the surface, never a beat flash
  noFill();
  for (let i = 0; i < 3; i++) {
    const life = ((K.t * (.06 + i * .017) * P.speed + fr(i + 41)) % 1);
    const rx = width * (.15 + fr(i * 3 + 42) * .7), ry = wy + (.25 + fr(i * 3 + 43) * .6) * (height - wy);
    const rr = life * u * .16 * (.5 + rip);
    strokeWeight(Math.max(.5, u * .0012 * (1 - life)));
    stroke(glC[0], glC[1] * .6, glC[2], 26 * (1 - life) * (.3 + .7 * en));
    ellipse(rx, ry, rr * 2, rr * .5);
  }
  noStroke();
}

scr(S.mist1, -K.t * u * .0081 * P.speed - u * .3, u * .015, 100 * Math.min(1, mistAmt * .8));

// the mirror line itself — the hardest edge in the frame
noFill(); strokeWeight(Math.max(.6, u * .0014));
stroke(glC[0], glC[1] * .5, glC[2], (16 + 26 * en) * (st.wire ? .6 : 1));
line(0, wy, width, wy);
noStroke();

if (st.grain > 6) {
  const ng = Math.floor(st.grain * 6);
  for (let i = 0; i < ng; i++) {
    const gx = ((fr(i * 3 + 801) * width) + Math.sin(K.t * .011 + i) * u * .003 + width) % width;
    const gy = fr(i * 3 + 802) * height;
    fill(hw(st.dark[0] + ho), st.dark[1] * .5, fr(i * 3 + 803) > .5 ? 93 : 5, 3 + fr(i) * 6);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .055);
  stroke(hw(st.dark[0] + ho), st.dark[1], st.blot ? 40 : 6, 20 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();

if (P.alpha < 1) { fill(hw(st.dark[0] + ho), st.dark[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
